+import { parseSeatCode } from './booking';
+
+describe('parseSeatCode', () => {
+  it('parst einen einstelligen Sitzplatz-Code in RowLabel und ColumnNumber', () => {
+    expect(parseSeatCode('B3')).toEqual({ rowLabel: 'B', columnNumber: 3 });
+  });
+
+  it('parst eine zweistellige Spaltennummer korrekt', () => {
+    expect(parseSeatCode('C12')).toEqual({ rowLabel: 'C', columnNumber: 12 });
+  });
+
+  it('wirft bei einem Code mit vertauschter Reihenfolge (Ziffer vor Buchstabe)', () => {
+    expect(() => parseSeatCode('3B')).toThrow();
+  });
+
+  it('wirft bei einem Code ohne Spaltennummer', () => {
+    expect(() => parseSeatCode('B')).toThrow();
+  });
+
+  it('wirft bei einem leeren Code', () => {
+    expect(() => parseSeatCode('')).toThrow();
+  });
+});
diff --git a/seed-a-frontend/src/app/core/api/booking.ts b/seed-a-frontend/src/app/core/api/booking.ts
index 6dfd731..284e24a 100644
--- a/seed-a-frontend/src/app/core/api/booking.ts
+++ b/seed-a-frontend/src/app/core/api/booking.ts
@@ -28,3 +28,11 @@ export interface CreateBookingRequest {
   email: string;
   positionen: CreateBookingPositionRequest[];
 }
+
+export function parseSeatCode(seatCode: string): { rowLabel: string; columnNumber: number } {
+  const match = /^([A-Za-z]+)(\d+)$/.exec(seatCode);
+  if (!match) {
+    throw new Error(`Ungültiger Sitzplatz-Code: '${seatCode}'`);
+  }
+  return { rowLabel: match[1], columnNumber: Number(match[2]) };
+}
