1	using Microsoft.AspNetCore.Mvc;
2	using seed_a_backend.Api.Application;
3	using seed_a_backend.Api.Controllers.Dtos;
4	
5	namespace seed_a_backend.Api.Controllers;
6	
7	[ApiController]
8	[Route("api/bookings")]
9	public class BookingsController(BookingService bookingService) : ControllerBase
10	{
11	    [HttpPost]
12	    public async Task<ActionResult<BookingDto>> CreateBooking(CreateBookingRequestDto request, CancellationToken ct)
13	    {
14	        if (request.Positionen is null || request.Positionen.Any(p => p is null))
15	        {
16	            return BadRequest(new ErrorEnvelopeDto(
17	                "VALIDATION_ERROR", "Die Anfrage enthält ungültige oder unvollständige Daten."));
18	        }
19	
20	        var command = new CreateBookingCommand(
21	            request.EventId, request.Name, request.Email,
22	            request.Positionen
23	                .Select(p => new CreateBookingPositionCommand(p.RowLabel, p.ColumnNumber, p.PriceCategoryId))
24	                .ToList());
25	
26	        var result = await bookingService.CreateBookingAsync(command, ct);
27	
28	        return result switch
29	        {
30	            BookingCreateResult.Success s => Created($"/api/bookings/{s.Booking.Reference}", ToDto(s.Booking)),
31	            BookingCreateResult.EventNotFound => NotFound(new ErrorEnvelopeDto("EVENT_NOT_FOUND", "Veranstaltung nicht gefunden.")),
32	            BookingCreateResult.ValidationFailed v => BadRequest(new ErrorEnvelopeDto("VALIDATION_ERROR", v.Message)),
33	            BookingCreateResult.SeatConflict c => Conflict(new ErrorEnvelopeDto(
34	                "SEAT_CONFLICT", "Mindestens ein gewählter Sitzplatz ist inzwischen belegt.", c.ConflictingSeats)),
35	            _ => throw new InvalidOperationException("Unbekanntes BookingCreateResult."),
36	        };
37	    }
38	
39	    private static BookingDto ToDto(BookingResult result) => new(
40	        result.Reference, result.Name, result.Status,
41	        result.Positionen
42	            .Select(p => new BookingPositionDto(
43	                p.RowLabel, p.ColumnNumber,
44	                new PriceCategoryDto(p.Preiskategorie.Id, p.Preiskategorie.Name, p.Preiskategorie.Preis)))
45	            .ToList(),
46	        result.Gesamtpreis);
47	}
