3	public abstract record BookingCreateResult
4	{
5	    public sealed record Success(BookingResult Booking) : BookingCreateResult;
6	
7	    public sealed record EventNotFound : BookingCreateResult;
8	
9	    public sealed record ValidationFailed(string Message) : BookingCreateResult;
10	
11	    public sealed record SeatConflict(IReadOnlyList<string> ConflictingSeats) : BookingCreateResult;
12	}
